function updateTheme(){document.documentElement.dataset.theme=state.theme;const icon=$('themeBtn')?.querySelector('i');if(icon)icon.className=state.theme==='dark'?'fa-solid fa-moon':'fa-solid fa-sun';const side=$('sidebarThemeBtn');if(side){const si=side.querySelector('i');if(si)si.className=state.theme==='dark'?'fa-solid fa-moon':'fa-solid fa-sun'}
localStorage.setItem(STORAGE_THEME,state.theme)}
function updateSoundBtn(){const btn=$('soundBtn');if(!btn)return;const icon=btn.querySelector('i');if(icon)icon.className=state.soundOn?'fa-solid fa-volume-high':'fa-solid fa-volume-xmark'}
function updateBellBtn(){const btn=$('bellBtn');if(btn){const icon=btn.querySelector('i');if(icon)icon.className=state.notificationsOn?'fa-solid fa-bell':'fa-regular fa-bell';btn.classList.toggle('active',state.notificationsOn)}
const side=$('sidebarBellBtn');if(side)side.classList.toggle('active',state.notificationsOn);}
function toast(msg,icon){const box=$('toasts');if(!box)return;const el=document.createElement('div');el.className='toast';const ico=icon||'circle-info';el.innerHTML=`<i class="fa-solid fa-${ico}"></i><span>${escapeHtml(msg)}</span>`;box.appendChild(el);setTimeout(()=>{el.style.transition='opacity .4s';el.style.opacity='0'},2000);setTimeout(()=>el.remove(),2500)}
function openSidebar(){$('sidebar').classList.add('open');$('overlay').classList.add('show')}
function closeSidebar(){$('sidebar').classList.remove('open');$('overlay').classList.remove('show')}
function showView(view){$('timerView').classList.toggle('hidden',view!=='timer');$('notepadPanel').classList.toggle('active',view==='notepad');$('soundPanel').classList.toggle('active',view==='sound');$('settingsPanel').classList.toggle('active',view==='settings');$('shieldPanel').classList.toggle('active',view==='shield');$('todoPanel').classList.toggle('active',view==='todo');window.scrollTo({top:0,behavior:'smooth'})}
let currentNoteId=null;function slugify(title){return(title||'untitled').toLowerCase().replace(/[\\/:*?"<>|]+/g,'').replace(/\s+/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'').slice(0,60)||'untitled'}
function uniqueFilename(title,excludeId){const base=slugify(title);let name=base;let i=2;while(Object.values(notesCache).some(n=>n.id!==excludeId&&n.filename===name)){name=`${base}_${i++}`}
return name}
async function newNote(){const id='n'+Date.now()+Math.random().toString(36).slice(2,6);const now=Date.now();const note={id,title:'Untitled',body:'',filename:uniqueFilename('Untitled',id),created:now,edited:now};notesCache[id]=note;currentNoteId=id;await saveSingleNote(note);openNotepad(id);renderNotesList()}
async function openNotepad(id){showView('notepad');if(id!==undefined)currentNoteId=id||null;await loadAllNotes();renderNotesList();updateRecentNotes();if(currentNoteId&&notesCache[currentNoteId])loadNoteIntoEditor(currentNoteId);else clearEditor()}
function loadNoteIntoEditor(id){const note=notesCache[id];if(!note){clearEditor();return}
$('noteTitle').value=note.title;$('noteBody').value=note.body;$('noteCreated').textContent='Created: '+relativeTime(note.created);$('noteEdited').textContent='Edited: '+relativeTime(note.edited);$('noteCount').textContent=note.body.length+' chars';document.querySelectorAll('.note-row').forEach(r=>{r.classList.toggle('active',r.dataset.noteId===id)})}
function clearEditor(){$('noteTitle').value='';$('noteBody').value='';$('noteCreated').textContent='Created: —';$('noteEdited').textContent='Edited: —';$('noteCount').textContent='0 chars';document.querySelectorAll('.note-row').forEach(r=>r.classList.remove('active'))}
async function persistCurrentNote(){const title=($('noteTitle').value||'').trim();const body=$('noteBody').value||'';if(!currentNoteId){if(!title&&!body)return;const id='n'+Date.now()+Math.random().toString(36).slice(2,6);const now=Date.now();notesCache[id]={id,title:title||'Untitled',body,filename:uniqueFilename(title||'Untitled',id),created:now,edited:now};currentNoteId=id}
const note=notesCache[currentNoteId];if(!note)return;note.title=title||'Untitled';note.body=body;note.filename=uniqueFilename(note.title,currentNoteId);note.edited=Date.now();await saveSingleNote(note);$('noteEdited').textContent='Edited: just now';$('noteCount').textContent=body.length+' chars';renderNotesList();updateRecentNotes()}
function renderNotesList(){const el=$('notesList');const notes=Object.values(notesCache).sort((a,b)=>b.edited-a.edited);if(!notes.length){el.innerHTML=`<div class="notes-empty">
            <i class="fa-solid fa-feather-pointed"></i>
            <p>No notes yet — click New to begin.</p>
        </div>`;return}
el.innerHTML=notes.map(n=>`
        <div class="note-row ${n.id === currentNoteId ? 'active' : ''}" data-note-id="${escapeAttr(n.id)}">
            <i class="fa-solid fa-feather-pointed nr-icon"></i>
            <div class="nr-main">
                <div class="nr-title">${escapeHtml(n.title || 'Untitled')}</div>
                <div class="nr-meta">${escapeHtml(firstLine(n.body))} · ${relativeTime(n.edited)}</div>
            </div>
            <button class="nr-del" data-del="${escapeAttr(n.id)}" title="Delete">
                <i class="fa-solid fa-trash-can"></i>
            </button>
        </div>`).join('');el.querySelectorAll('.note-row').forEach(row=>{row.addEventListener('click',async(e)=>{if(e.target.closest('.nr-del'))return;if(currentNoteId)await persistCurrentNote();currentNoteId=row.dataset.noteId;loadNoteIntoEditor(currentNoteId);renderNotesList()})});el.querySelectorAll('.nr-del').forEach(btn=>{btn.addEventListener('click',async(e)=>{e.stopPropagation();await deleteNote(btn.dataset.del)})})}
async function deleteNote(id){if(!confirm('Delete this note?'))return;await deleteSingleNote(id);if(currentNoteId===id){currentNoteId=null;clearEditor()}
renderNotesList();updateRecentNotes();toast('Note deleted','trash-can')}
async function exportCurrentNote(){if(!currentNoteId)return;await persistCurrentNote();const note=notesCache[currentNoteId];if(!note)return;const body=serializeCrocusNote(note);const blob=new Blob([body],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(note.filename||'note')+'.crocusnote';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Exported .crocusnote','file-export')}
function importNoteFile(file){const reader=new FileReader();reader.onload=async()=>{const text=String(reader.result||'');const parsed=parseCrocusNote(text,file.name);const id='n'+Date.now()+Math.random().toString(36).slice(2,6);const note={id,title:parsed.title||file.name.replace(/\.crocusnote$/i,''),body:parsed.body||'',filename:uniqueFilename(parsed.title||file.name,id),created:parsed.created||Date.now(),edited:parsed.edited||Date.now()};notesCache[id]=note;currentNoteId=id;await saveSingleNote(note);openNotepad(id);renderNotesList();updateRecentNotes();toast('Imported','file-import')};reader.readAsText(file)}
let tasks=[];let todoFilter='all';function parseTasks(text){const out=[];for(const raw of(text||'').split('\n')){const line=raw.trim();if(!line||line.startsWith('#'))continue;const m=line.match(/^\[([ xX])\]\s*(.+)$/);if(!m)continue;const done=m[1].toLowerCase()==='x';let rest=m[2];const meta={};const parts=rest.split('|').map(s=>s.trim());rest=parts[0];for(let i=1;i<parts.length;i++){const idx=parts[i].indexOf(':');if(idx>0){const k=parts[i].slice(0,idx).trim();const v=parts[i].slice(idx+1).trim();if(k)meta[k]=v}}
out.push({id:'t'+out.length+'_'+Date.now()+Math.random().toString(36).slice(2,5),text:rest,done,meta})}
return out}
function serializeTasks(list){return list.map(t=>{const box=t.done?'[x]':'[ ]';let line=`${box} ${t.text}`;for(const k in(t.meta||{})){if(t.meta[k]===''||t.meta[k]==null)continue;line+=` | ${k}:${t.meta[k]}`}
return line}).join('\n')+'\n'}
async function loadTasks(){try{const r=await fetch(API_TASKS);if(!r.ok)throw new Error();const text=await r.text();tasks=parseTasks(text)}catch(_){try{tasks=JSON.parse(localStorage.getItem('crocus_tasks')||'[]');if(!Array.isArray(tasks))tasks=[];tasks.forEach(t=>{if(!t.meta)t.meta={}})}catch(_){tasks=[]}}
refreshRecurringTasks()}
async function saveTasks(){const body=serializeTasks(tasks);try{await fetch(API_TASKS,{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body})}catch(_){localStorage.setItem('crocus_tasks',JSON.stringify(tasks))}}
function refreshRecurringTasks(){const today=todayISO();let changed=!1;for(const t of tasks){const repeat=t.meta&&t.meta.repeat;if(!repeat||!REPEAT_DAYS[repeat])continue;if(!t.done)continue;const doneDate=t.meta.done||today;const elapsed=daysBetween(doneDate,today);if(elapsed>=REPEAT_DAYS[repeat]){t.done=!1;delete t.meta.done;changed=!0}}
if(changed)saveTasks();}
function repeatBadgeHtml(task){const r=task.meta&&task.meta.repeat;if(!r||!REPEAT_DAYS[r])return'';return `<span class="task-badge" title="Repeats ${r}"><i class="fa-solid fa-rotate"></i> ${r}</span>`}
async function openTodo(){showView('todo');await loadTasks();renderTodoList()}
function renderTodoList(){const el=$('todoList');if(!el)return;let filtered=tasks;if(todoFilter==='active')filtered=tasks.filter(t=>!t.done);else if(todoFilter==='done')filtered=tasks.filter(t=>t.done);if(!tasks.length){el.innerHTML=`<div class="todo-empty">
            <i class="fa-solid fa-list-check"></i>
            <p>Nothing on your list yet.</p>
        </div>`}else if(!filtered.length){el.innerHTML=`<div class="todo-empty">
            <i class="fa-solid fa-check"></i>
            <p>All clear here.</p>
        </div>`}else{el.innerHTML=filtered.map(t=>{const active=state.activeTaskId===t.id;return `
            <div class="todo-item ${t.done ? 'done' : ''} ${active ? 'is-active' : ''}" data-id="${escapeAttr(t.id)}">
                <input type="checkbox" ${t.done ? 'checked' : ''} data-toggle="${escapeAttr(t.id)}" />
                <div class="todo-main">
                    <span class="todo-text" contenteditable="true" data-edit="${escapeAttr(t.id)}">${escapeHtml(t.text)}</span>
                    ${repeatBadgeHtml(t)}
                </div>
                <button class="todo-play" data-play="${escapeAttr(t.id)}" title="Focus on this task">
                    <i class="fa-solid ${active ? 'fa-circle-dot' : 'fa-play'}"></i>
                </button>
                <button class="todo-del" data-del="${escapeAttr(t.id)}">
                    <i class="fa-solid fa-xmark"></i>
                </button>
            </div>`}).join('')}
const activeCount=tasks.filter(t=>!t.done).length;$('todoCount').textContent=`${activeCount} active · ${tasks.length} total`;el.querySelectorAll('[data-toggle]').forEach(cb=>{cb.addEventListener('change',()=>{const t=tasks.find(x=>x.id===cb.dataset.toggle);if(t){t.done=cb.checked;t.meta=t.meta||{};if(cb.checked){t.meta.done=todayISO();if(state.activeTaskId===t.id)detachActiveTask();}else{delete t.meta.done}
saveTasks();renderTodoList()}})});el.querySelectorAll('[data-play]').forEach(btn=>{btn.addEventListener('click',()=>{const t=tasks.find(x=>x.id===btn.dataset.play);if(!t)return;if(state.activeTaskId===t.id)detachActiveTask();else setActiveTask(t)})});el.querySelectorAll('[data-del]').forEach(btn=>{btn.addEventListener('click',()=>{tasks=tasks.filter(x=>x.id!==btn.dataset.del);if(state.activeTaskId===btn.dataset.del)detachActiveTask();saveTasks();renderTodoList()})});el.querySelectorAll('[data-edit]').forEach(sp=>{sp.addEventListener('blur',()=>{const t=tasks.find(x=>x.id===sp.dataset.edit);const newText=sp.textContent.trim();if(t&&newText&&newText!==t.text){t.text=newText;saveTasks()}else if(t)sp.textContent=t.text});sp.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();sp.blur()}})})}
async function addTodo(){const input=$('todoInput');const text=input.value.trim();if(!text)return;const repeatSel=$('todoRepeat');const repeat=repeatSel?repeatSel.value:'once';const meta={};if(repeat&&repeat!=='once')meta.repeat=repeat;tasks.unshift({id:'t'+Date.now()+Math.random().toString(36).slice(2,6),text,done:!1,created:Date.now(),meta});input.value='';await saveTasks();renderTodoList()}
async function clearDoneTasks(){const before=tasks.length;tasks=tasks.filter(t=>!t.done||(t.meta&&t.meta.repeat&&REPEAT_DAYS[t.meta.repeat]));if(tasks.length===before){toast('Nothing to clear','circle-info');return}
await saveTasks();renderTodoList();toast('Cleared completed','broom')}
let blocklistPollTimer=null;let prefocusSelected=new Set();async function openShield(){showView('shield');await loadBlocklist();await refreshBlockStatus()}
async function loadBlocklist(){try{const r=await fetch(API_BLOCKLIST);if(!r.ok)throw new Error();const data=await r.json();const list=data.blocked||[];$('blocklistTextarea').value=list.join('\n');updateBlocklistCount()}catch(_){$('blocklistTextarea').value=''}}
async function saveBlocklist(){const text=$('blocklistTextarea').value;try{const r=await fetch(API_BLOCKLIST,{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body:text});if(!r.ok)throw new Error();const res=await r.json();if(res.in_sync){toast('Blocklist applied','shield-halved')}else if(res.spawned){toast('Approve the admin prompt to apply','shield-halved');startBlocklistStatusPoll()}else{toast('Saved, but not applied — run as admin','triangle-exclamation')}
await loadBlocklist();await refreshBlockStatus()}catch(_){toast('Could not save blocklist','triangle-exclamation')}}
function startBlocklistStatusPoll(){if(blocklistPollTimer)clearInterval(blocklistPollTimer);let tries=0;blocklistPollTimer=setInterval(async()=>{tries++;try{const r=await fetch(API_BLOCKLIST_STATUS);const s=await r.json();if(s.in_sync){clearInterval(blocklistPollTimer);blocklistPollTimer=null;toast('Blocklist applied','check');await refreshBlockStatus()}else if(tries>60){clearInterval(blocklistPollTimer);blocklistPollTimer=null}}catch(_){}},500)}
async function refreshBlockStatus(){try{const r=await fetch(API_BLOCKLIST_STATUS);if(!r.ok)throw new Error();const s=await r.json();const el=$('proxyStatus');if(!el)return;const dot=el.querySelector('.dot');const txt=$('proxyStatusText');if(s.in_sync){dot.className='dot on';txt.textContent=s.admin?'Active (admin)':'Active'}else{dot.className='dot off';txt.textContent='Not applied — click Save'}
$('blockedToday').textContent=s.admin?`${s.count} sites blocked`:`${s.count} sites pending`;$('blocklistCount').textContent=`${s.count} site${s.count === 1 ? '' : 's'}`}catch(_){const el=$('proxyStatus');if(el){$('proxyStatusText').textContent='Server unavailable';el.querySelector('.dot').className='dot off'}}}
function updateBlocklistCount(){const lines=$('blocklistTextarea').value.split('\n').map(s=>s.trim()).filter(s=>s&&!s.startsWith('#'));$('blocklistCount').textContent=`${lines.length} site${lines.length === 1 ? '' : 's'}`}
function buildBlockingQuickGrid(){const el=$('blockingQuickGrid');if(!el)return;el.innerHTML=COMMON_BLOCKLIST.map(d=>`<button data-domain="${escapeAttr(d)}">${escapeHtml(d)}</button>`).join('');el.querySelectorAll('button').forEach(b=>{b.addEventListener('click',()=>addDomainToBlocklist(b.dataset.domain))})}
function addDomainToBlocklist(domain,opts={}){const ta=$('blocklistTextarea');const clean=cleanDomain(domain);if(!clean)return!1;const lines=ta.value.split('\n').map(l=>l.trim());const exists=lines.some(l=>l.toLowerCase()===clean);if(exists){if(!opts.silent)toast('Already in list','circle-info');return!1}
lines.push(clean);ta.value=lines.filter((l,i)=>l||i===lines.length-1).join('\n');updateBlocklistCount();if(!opts.silent)toast(`Added ${clean}`,'plus');return!0}
async function addDomainFromInput(){const input=$('blockQuickAdd');const domain=cleanDomain(input.value);if(!domain)return;const added=addDomainToBlocklist(domain);input.value='';if(added)await saveBlocklist();}
async function shieldQuickBlock(){const input=$('shieldBlockInput');if(!input)return;const domain=cleanDomain(input.value);if(!domain)return;try{const r=await fetch(API_BLOCKLIST);const data=r.ok?await r.json():{blocked:[]};const list=data.blocked||[];if(list.map(d=>d.toLowerCase()).includes(domain)){toast('Already blocked','circle-info');input.value='';return}
list.push(domain);const text=list.join('\n');const saveR=await fetch(API_BLOCKLIST,{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body:text});const res=await saveR.json();input.value='';if(res.in_sync){toast(`Blocked ${domain}`,'shield-halved')}else if(res.spawned){toast(`Approve admin to block ${domain}`,'shield-halved');startBlocklistStatusPoll()}else{toast('Saved — needs admin','triangle-exclamation')}
if($('shieldPanel').classList.contains('active')){await loadBlocklist();await refreshBlockStatus()}}catch(_){toast('Server offline — cannot block','triangle-exclamation')}}
async function openPreFocusModal(){try{const r=await fetch(API_BLOCKLIST);if(!r.ok)throw new Error();const data=await r.json();const current=new Set((data.blocked||[]).map(d=>d.toLowerCase()));prefocusSelected=new Set(COMMON_BLOCKLIST.filter(d=>current.has(d.toLowerCase())));const grid=$('prefocusGrid');grid.innerHTML=COMMON_BLOCKLIST.map(d=>{const checked=prefocusSelected.has(d);return `<div class="prefocus-item ${checked ? 'checked' : ''}" data-domain="${escapeAttr(d)}">
                <input type="checkbox" id="pf_${escapeAttr(d)}" ${checked ? 'checked' : ''} />
                <label for="pf_${escapeAttr(d)}">${escapeHtml(d)}</label>
            </div>`}).join('');grid.querySelectorAll('.prefocus-item').forEach(item=>{const cb=item.querySelector('input');item.addEventListener('click',(e)=>{if(e.target===cb||e.target.tagName==='LABEL')return;cb.checked=!cb.checked;cb.dispatchEvent(new Event('change'))});cb.addEventListener('change',()=>{const d=item.dataset.domain;if(cb.checked){prefocusSelected.add(d);item.classList.add('checked')}else{prefocusSelected.delete(d);item.classList.remove('checked')}})});const customInput=$('prefocusCustomInput');if(customInput)customInput.value='';$('preFocusModal').classList.add('open')}catch(_){toast('Server offline — starting without blocking','circle-info');actuallyStartFocus()}}
function closePreFocusModal(){$('preFocusModal').classList.remove('open')}
async function confirmPreFocusAndStart(){try{const r=await fetch(API_BLOCKLIST);const data=r.ok?await r.json():{blocked:[]};const existing=new Set((data.blocked||[]).map(d=>d.toLowerCase()));for(const d of COMMON_BLOCKLIST){if(prefocusSelected.has(d))existing.add(d.toLowerCase());else existing.delete(d.toLowerCase())}
const customInput=$('prefocusCustomInput');const custom=cleanDomain(customInput?.value||'');if(custom)existing.add(custom);const text=Array.from(existing).sort().join('\n');const saveR=await fetch(API_BLOCKLIST,{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body:text});const res=await saveR.json();if(res.spawned&&!res.in_sync){toast('Approve admin prompt to apply blocks','shield-halved');startBlocklistStatusPoll()}}catch(_){}
closePreFocusModal();actuallyStartFocus()}
function openSettings(){showView('settings');renderSettings()}
function renderSettings(){$('setFocus').value=state.durations.focus;$('setShort').value=state.durations.short;$('setLong').value=state.durations.long;$('setLongEvery').value=state.longEvery;renderSettingsPreview()}
function renderSettingsPreview(){const seq=[];for(let i=1;i<=state.longEvery;i++){seq.push(state.durations.focus);if(i<state.longEvery)seq.push(state.durations.short);else seq.push(state.durations.long)}
$('settingsPreview').textContent=seq.join(' · ')}
function clampSetting(key,value){const lim=LIMITS[key];if(!lim)return value;let v=parseInt(value,10);if(isNaN(v))v=(key==='longEvery')?state.longEvery:state.durations[key];return Math.max(lim.min,Math.min(lim.max,v))}
function applySettings(){state.durations.focus=clampSetting('focus',$('setFocus').value);state.durations.short=clampSetting('short',$('setShort').value);state.durations.long=clampSetting('long',$('setLong').value);state.longEvery=clampSetting('longEvery',$('setLongEvery').value);if(state.cyclePos>=state.longEvery)state.cyclePos=state.cyclePos%state.longEvery;if(!state.running){state.totalSeconds=state.durations[state.mode]*60;state.seconds=state.totalSeconds}
renderSettings();updateTimer();updateDots();updateStats();persistState()}
function applyPreset(name){const p=PRESETS[name];if(!p)return;state.durations={focus:p.focus,short:p.short,long:p.long};state.longEvery=p.longEvery;if(state.cyclePos>=state.longEvery)state.cyclePos=state.cyclePos%state.longEvery;if(!state.running){state.totalSeconds=state.durations[state.mode]*60;state.seconds=state.totalSeconds}
renderSettings();updateTimer();updateDots();updateStats();persistState();toast('Preset applied','wand-magic-sparkles')}
function resetSettings(){if(!confirm('Reset all durations to defaults?'))return;state.durations={...DEFAULT_DURATIONS};state.longEvery=DEFAULT_LONG_EVERY;state.cyclePos=0;if(!state.running){state.totalSeconds=state.durations[state.mode]*60;state.seconds=state.totalSeconds}
renderSettings();updateTimer();updateDots();updateStats();persistState();toast('Reset to defaults','rotate-left')}
function openModal(){$('screenModal').classList.add('open');renderModalChart()}
function closeModal(){$('screenModal').classList.remove('open')}
function renderModalChart(){const chart=$('modalChart');$('modalTodayTotal').textContent=formatHM(state.screenSecondsToday);const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const today=new Date();const values=[];for(let i=6;i>=0;i--){const d=new Date(today);d.setDate(today.getDate()-i);const key=d.toDateString();const entry=state.history.find(h=>h.date===key);values.push({label:days[d.getDay()],value:entry?entry.seconds:0,today:i===0})}
const max=Math.max(...values.map(v=>v.value),60);chart.innerHTML=values.map(v=>{const pct=Math.max(3,(v.value/max)*100);return `<div class="bar-group">
            <div class="bar ${v.today ? 'today' : ''}" style="height:${pct}%"></div>
            <span class="day-label">${v.label}</span>
        </div>`}).join('')}
function saveHistoryEntry(){const today=new Date().toDateString();const last=state.history[state.history.length-1];if(!last||last.date!==today){state.history.push({date:today,seconds:state.screenSecondsToday});if(state.history.length>30)state.history.shift();}else{last.seconds=state.screenSecondsToday}}
function persistState(){try{saveHistoryEntry();localStorage.setItem(STORAGE_STATE,JSON.stringify(state))}catch(_){}}
function loadState(){try{const raw=localStorage.getItem(STORAGE_STATE);if(!raw)return;const parsed=JSON.parse(raw);Object.assign(state,parsed);if(!state.durations)state.durations={...DEFAULT_DURATIONS};if(typeof state.longEvery!=='number')state.longEvery=DEFAULT_LONG_EVERY;if(!Array.isArray(state.history))state.history=[];if(!Array.isArray(state.sessionLog))state.sessionLog=[];if(typeof state.activeTaskId==='undefined')state.activeTaskId=null;if(typeof state.activeTaskName==='undefined')state.activeTaskName=null}catch(_){}}
function checkDailyReset(){const today=new Date().toDateString();const last=localStorage.getItem(STORAGE_LASTDATE);if(last!==today){state.sessionsToday=0;state.focusSecondsToday=0;state.breakSecondsToday=0;state.screenSecondsToday=0;state.flowersToday=0;state.heartsToday=0;state.cyclePos=0;state.sessionLog=[];state.longestStreak=state.streak;localStorage.setItem(STORAGE_LASTDATE,today);saveHistoryEntry()}}
function escapeHtml(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function escapeAttr(s){return escapeHtml(s)}
function handleKey(e){const tag=(e.target.tagName||'').toUpperCase();if(tag==='INPUT'||tag==='TEXTAREA'||e.target.isContentEditable){if(e.key==='Escape')e.target.blur();return}
if(e.key===' '||e.code==='Space'){if($('timerView').classList.contains('hidden'))return;e.preventDefault();startTimer();return}
if(e.key==='r'||e.key==='R')resetTimer();if(e.key==='s'||e.key==='S')skipTimer();if(e.key==='n'||e.key==='N')openNotepad();if(e.key==='t'||e.key==='T')openTodo();if(e.key==='m'||e.key==='M')openSound();if(e.key==='b'||e.key==='B')openShield();if(e.key==='1')setMode('focus');if(e.key==='2')setMode('short');if(e.key==='3')setMode('long');if(e.key==='Escape'){closeModal();closeSidebar();closePreFocusModal();if($('shieldOverlay').classList.contains('active')){state.shieldEnabled=!1;updateShield();toast('Shield released','shield')}
if($('notepadPanel').classList.contains('active')){persistCurrentNote();showView('timer')}
if($('soundPanel').classList.contains('active'))showView('timer');if($('settingsPanel').classList.contains('active'))showView('timer');if($('shieldPanel').classList.contains('active'))showView('timer');if($('todoPanel').classList.contains('active'))showView('timer');}}
