function toggleNotifications(){if(!('Notification' in window)){toast('Notifications not supported','triangle-exclamation');return}
if(Notification.permission==='granted'){state.notificationsOn=!state.notificationsOn;updateBellBtn();toast(state.notificationsOn?'Notifications on':'Notifications off','bell');return}
if(Notification.permission==='denied'){toast('Notifications blocked in browser','bell-slash');return}
Notification.requestPermission().then(p=>{if(p==='granted'){state.notificationsOn=!0;updateBellBtn();toast('Notifications enabled','bell')}else{toast('Permission denied','bell-slash')}})}
function openSound(){showView('sound');buildSoundPanel();loadCustomSounds(!1)}
async function init(){loadState();checkDailyReset();const savedTheme=localStorage.getItem(STORAGE_THEME);if(savedTheme)state.theme=savedTheme;updateTheme();updateSoundBtn();updateBellBtn();updateClock();setMode('focus');updateTimer();updateDots();refreshTimerQuote();buildQuickPick();buildSoundPanel();await probeServer();await loadAllNotes();renderNotesList();clearEditor();updateStats();await loadTasks();renderActiveTask();updateShield();renderSettings();wireEvents();console.log('Crocus loaded. Space: start · R: reset · S: skip · N: notes · T: todo · M: music · B: block')}
